I'll write the file with a retry helper that only retries `ServerBusy` with exponential backoff, then use it for the `goTo('sol_belt')` call.

```ts
import {goTo, isError} from 'play';

/**
 * Try `fn` up to 6 times (1 initial + 5 retries). Only `ServerBusy` is retried;
 * backoff is exponential from 1s. Any other error rejects immediately.
 */
async function goToRetry(id: string) {
  const attempts = 6;
  const baseMs = 1_000;
  let attempt = 0;
  for (;;) {
    attempt++;
    try {
      return await goTo(id);
    } catch (e) {
      // Only the transient ServerBusy error is retryable; anything else fails.
      if (isError(e, 'ServerBusy') && attempt < attempts) {
        const delay = baseMs * 2 ** (attempt - 1); // 1s, 2s, 4s, 8s, 16s
        await sleep(delay);
        continue;
      }
      throw e;
    }
  }
}

/** Wait in game time. Only used between ServerBusy retries. */
function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

export default async function main() {
  await goToRetry('sol_belt');
}
