export default async function main() {
  // Move to the mining belt (no-op flight if we are already there).
  await goTo('sol_belt');

  // Mine repeatedly until the hold is full (mine rejects with HoldFull once it is).
  let first = true;
  for (;;) {
    try {
      await mine();
    } catch (e) {
      if (isError(e, 'HoldFull')) break;   // hold is full -> stop mining
      if (first) throw e;                  // never got a single cycle: nothing to do, fail
      break;                              // some other, unexpected state: stop
    }
    first = false;
  }

  // Go to the base; this flies there and docks.
  await goTo('sol_base');

  // Read what is actually in the hold.
  const present = await orient();

  // Sell every item, whole quantity each (omit quantity => "all of it").
  const rows = present.cargo.map((r) => ({item_id: r.item_id, quantity: r.quantity}));

  // If somehow the hold is empty, selling would reject with NoBuyer; guard against that.
  if (rows.length === 0) return;

  const sold = await sell(rows);

  // (Journaling is optional; the task only requires the sell. Kept light on purpose.)
}
