import {Effect} from 'effect';
import {goTo, hunt, disengage, note} from 'play';

export default Effect.gen(function* () {
  yield* goTo('sol_nebula');
  const result = yield* Effect.either(hunt({fights: 2}));
  yield* disengage();
  if (Effect.isLeft(result)) {
    yield* Effect.fail(result.left);
  }
  yield* note(`hunt ended: ${result.right.ended} (${result.right.fights.length} fights)`);
});
