import {goTo, hunt, disengage, isError} from 'play';

export default async function main() {
  let huntError: unknown = null;
  let ranHunt = false;

  try {
    try {
      await goTo('sol_nebula');
    } catch (e) {
      if (isError(e, 'InBattle')) {
        // Already in battle here; leave it, then proceed to the nebula.
        await disengage();
        await goTo('sol_nebula');
      } else {
        throw e; // UnknownPlace / NoFuel / ServerBusy — fail the program, but disengage runs below.
      }
    }

    try {
      await hunt({fights: 2});
      ranHunt = true;
    } catch (e) {
      // NothingHere / HullCritical (or InBattle) — record so the program still fails.
      ranHunt = true;
      huntError = e;
    }
  } finally {
    // Required: disengage() must run at the end of the program, after the hunt, whatever happened.
    await disengage();
  }

  // Any failure from the hunt still fails the program.
  if (huntError !== null) {
    throw huntError;
  }
}
