import {Effect, Schema} from 'effect';
import {
  orient,
  prices,
  missions,
  note,
  type Quote,
  type Mission,
  type Present,
} from 'play';

export default Effect.gen(function* () {
  // All three are independent, so run them concurrently with Effect.all.
  const [pres, quotes, board] = yield* Effect.all([orient(), prices(), missions()]);

  // The item with the highest best_buy price.
  const top = quotes.reduce((best: Quote | undefined, q) =>
    best === undefined || q.best_buy > best.best_buy ? q : best,
  );

  const topId = top === undefined ? 'none' : top.item_id;
  const nMissions = board.length;

  yield* note(
    `credits ${pres.credits}; highest best_buy ${topId}; missions ${nMissions}`,
  );
});
