import {
  readMarket,
  sell,
  note,
  orient,
  MarketBook,
} from 'play';

export default Effect.gen(function* () {
  // I hold this (right here, since I am docked at sol_base)
  const present = yield* orient();
  const book: unknown = yield* readMarket();
  const decoded = yield* Schema.decodeUnknown(MarketBook)(book).pipe(
    Effect.catchAll(() =>
      Effect.gen(function* () {
        yield* note('bad book');
        return null;
      })(),
    ),
  );

  if (decoded === null) {
    return; // finished without failing
  }

  const sellable = present.cargo.filter((row) => {
    const q = decoded.rows.find((r) => r.item_id === row.item_id);
    return q !== undefined && q.best_buy >= 10;
  });

  if (sellable.length > 0) {
    yield* sell(sellable);
  }

  return;
});
