import {orient, readMarket, sell, note, decode, MarketBook, isError} from 'play';

export default async function main() {
  const present = await orient();
  const heldItems = new Map(present.cargo.map((row) => [row.item_id, row.quantity]));

  let toSell: {item_id: string; quantity?: number}[] = [];

  try {
    const raw = await readMarket();
    const book = decode(MarketBook, raw);

    // Build a lookup of best_buy by item
    const bestBuyByItem = new Map<string, number>(
      book.rows.map((r) => [r.item_id, r.best_buy])
    );

    for (const [item_id, quantity] of heldItems) {
      const bestBuy = bestBuyByItem.get(item_id);
      if (bestBuy !== undefined && bestBuy >= 10) {
        toSell.push({item_id, quantity});
      }
    }
  } catch (e) {
    if (isError(e, 'BadData')) {
      note("bad book");
      return;
    }
    throw e; // Not a decode failure, something else went wrong
  }

  if (toSell.length > 0) {
    const sold = await sell(toSell);
    note(`sold for ${sold.total}`);
  }
}
