import {Effect} from 'effect';
import {missions, acceptMission, completeMissions, note} from 'play';

export default Effect.gen(function* () {
  const board = yield* missions();

  const want = board.filter((m) => m.reward >= 100);
  let accepted = 0;

  for (const m of want) {
    const res = yield* acceptMission(m.id).pipe(
      Effect.either,
    );
    if (res._tag === 'NoSlots') {
      break;
    }
    if (res._tag === 'Success') {
      accepted++;
    }
  }

  const done = yield* completeMissions().pipe(
    Effect.catchTag('NothingCompletable', (e) =>
      Effect.zipRight(note('no missions were completable'), 0),
    ),
  );

  return accepted;
});
