completion:
Here's the program. It lists the mission board, accepts every mission whose reward is at least 100 (stopping on `NoSlots`), then attempts `completeMissions()` (noting and carrying on if it comes back `NothingCompletable`), and returns how many were accepted.

```ts
import {acceptMission, completeMissions, isError, missions, note} from 'play';

export default async function main() {
  const board = await missions();
  let accepted = 0;
  for (const m of board) {
    if (m.reward < 100) continue;
    try {
      await acceptMission(m.id);
      accepted++;
    } catch (e) {
      if (isError(e, 'NoSlots')) {
        break;
      }
      throw e; // not ours to handle
    }
  }
  note(`accepted ${accepted} missions at sol_base`);
  try {
    const done = await completeMissions();
    note(`completed ${done.completed.length} missions for ${done.credits} credits`);
  } catch (e) {
    if (isError(e, 'NothingCompletable')) {
      note('no missions ready to deliver yet');
    } else {
      throw e; // not ours to handle
    }
  }
  return accepted;
}
