import {Effect, Schedule, Schema} from 'effect';
import {
  type Arrived, type Game, type Present, type Row, type Sold,
  goTo, mine, sell, service, completeMissions, disengage, orient, note,
  InBattle, HoldFull, NoFuel, ServerBusy, UnknownPlace,
  NoBuyer, NotDocked, NothingCompletable,
} from 'play';

const fullMine = (row: Row): Effect<void> =>
  Effect.gen(function* () {
    yield* Effect.succeed(row);
  });

export default Effect.gen(function* () {
  const held = (p: Present): number =>
    p.cargo.reduce((s, c) => s + c.quantity, 0);

  // helper: send a row along, or (on HoldFull) yield void
  const rowOrVoid = (e: Effect<Row, any, Game>): Effect<Row | void, any, Game> =>
    e.pipe(Effect.map(row => row as Row | void));

  const mineFill: Effect<Row | void, InBattle> = Effect.gen(function* () {
    for (;;) {
      const r = yield* rowOrVoid(mine()).pipe(
        Effect.catchTag('HoldFull', () => Effect.succeed(undefined as void)),
        Effect.catchTag('InBattle', err =>
          Effect.gen(function* () {
            yield* disengage();
            return err;
          })
        ),
      );
      if (r === undefined) return; // hold is full: stop filling
    }
  });

  const goToRetry: Effect<Arrived, InBattle | UnknownPlace> = (id: string) =>
    goTo(id).pipe(
      Effect.catchTag('NoFuel', () => Effect.die(`NoFuel to ${id}`)),
      Effect.retry(
        Schedule.recursWhile((_, attempt) => attempt > 0, e => e._tag !== 'ServerBusy'),
      ),
      Effect.catchTag('InBattle', err =>
        Effect.gen(function* () {
          yield* disengage();
          return err;
        })
      ),
    );

  const fillFrom = (poi: string, id: string): Effect<Row | void, InBattle | UnknownPlace> =>
    Effect.gen(function* () {
      yield* goToRetry(id);
      return yield* mineFill;
    });

  const finalNote = Effect.gen(function* () {
    const p = yield* orient();
    yield* note(`final credits: ${p.credits}`);
  });

  // 1. Go to kepler_belt, mining until the hold is full.
  const got = yield* fillFrom('kepler_belt', 'kepler_belt').pipe(
    Effect.match({
      onFailure: () =>
        Effect.gen(function* () {
          yield* goToRetry('sol_base').pipe(Effect.ignore);
          return undefined as Row | void;
        }),
      onSuccess: r => r,
    }),
  );
  // preserve the copper_ore row across the round-trip back to kepler_belt
  const copper: Row | undefined =
    got !== undefined
      ? {
          item_id: 'copper_ore',
          quantity: got.item_id === 'copper_ore' ? got.quantity : undefined,
        }
      : undefined;

  // 2. Go back to kepler_base.
  const back = yield* fillFrom('kepler_base', 'kepler_belt').pipe(
    Effect.match({
      onFailure: () => Effect.gen(function* () {
        yield* goToRetry('kepler_base').pipe(Effect.ignore);
        return undefined as Row | void;
      }),
      onSuccess: r => r,
    }),
  );
  // Now we are docked at kepler_base with cargo = (any pre-existing) + `back`.
  // The ship left kepler_belt with `got`, so `got` is already inside the hold.

  // 3. Sell your copper_ore.
  const sold: Sold | undefined = yield*
    sell([{item_id: 'copper_ore'}]).pipe(
      Effect.match({
        onFailure: () => Effect.void,
        onSuccess: s => s,
      }),
    );
  void sold;

  // 4. Service the ship.
  const didService = yield*
    service().pipe(Effect.match({onFailure: () => false, onSuccess: () => true}));
  void didService;

  // 5. Complete missions (ignore NothingCompletable).
  const didComplete = yield*
    completeMissions().pipe(
      Effect.match({
        onFailure: err => err._tag === 'NothingCompletable' ? true : false,
        onSuccess: () => true,
      }),
    );
  void didComplete;

  // 6. Whatever happened, last action: note current credits.
  yield* finalNote;
});
```

