import {goTo, mine, sell, service, completeMissions, note, orient, isError, sleep} from 'play';

export default async function main() {
  try {
    await goTo('kepler_belt');

    // Mine until the hold is full, disengaging from any pirate encounter in between.
    for (;;) {
      try {
        await mine();
      } catch (e) {
        if (isError(e, 'InBattle')) {
          await disengage();
          continue;                       // try to keep mining
        }
        if (isError(e, 'HoldFull')) {
          break;                          // hold is full, done mining
        }
        throw e;                          // no plan for this
      }
    }

    await goTo('kepler_base');
    await sell([{item_id: 'copper_ore'}]);
    await service();
    await completeMissions().catch((e) => {
      if (isError(e, 'NothingCompletable')) return;
      throw e;
    });
  } catch {
    // whatever happened, keep going to the final note
  }

  // The last thing the program does: record current credits.
  const present = await orient();
  note(`credits: ${present.credits}`);
}
