import {Effect} from 'effect';
import {goTo, disengage, note, GameError} from 'play';

export default Effect.gen(function* () {
  const arrival = yield* goTo('kepler_base').pipe(
    Effect.either(),
  );

  if (arrival._tag === 'Right') {
    return yield* note(`docked at kepler_base, used ${arrival.right.fuel_used} fuel`);
  }

  const err: GameError = arrival.left;
  if (err._tag === 'InBattle') {
    yield* disengage();
    const retry = yield* goTo('kepler_base').pipe(Effect.either());
    if (retry._tag === 'Right') {
      return yield* note(`docked at kepler_base after disengaging, used ${retry.right.fuel_used} fuel`);
    }
    return yield* note(`retry failed: ${retry.left._tag}`);
  }

  return yield* note(`failed: ${err._tag}`);
});
