      Effect.map((e) =>
        e._tag === 'InBattle' ? Effect.zipRight(disengage(), mine()) : Effect.fail(e)
      ),
      Effect.retry(
        Schedule.recursWhile((e) => e._tag === 'InBattle')
      )
    );
    if (outcome._tag === 'Left' && outcome.left._tag === 'HoldFull') break; // hold is full
    if (outcome._tag === 'Right') break; // failed for a reason we have no plan for
  }

