import {goTo, sleep, isError} from 'play';

/**
 * Fly to `id`, retrying only on the transient `ServerBusy` error.
 *
 * Exponential backoff starts at 1 second and doubles each retry: 1s, 2s, 4s, 8s, 16s.
 * At most 5 retries (so up to 6 attempts in total). Any other error is
 * re-thrown immediately — it is not retried and will fail the program.
 */
async function goToWithRetry(id: string) {
  const maxAttempts = 6; // 1 initial + 5 retries
  let delayMs = 1000;

  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    try {
      return await goTo(id);
    } catch (e) {
      // Only ServerBusy is transient. Everything else re-throws untouched.
      if (!isError(e, 'ServerBusy')) throw e;

      if (attempt === maxAttempts) {
        // Out of retries; let the program fail with the last error.
        throw e;
      }

      // Wait, then double the backoff for the next retry.
      await sleep(delayMs);
      delayMs *= 2;
    }
  }

  // Unreachable: the loop above always returns or throws.
  throw new Error('unreachable');
}

export default async function main() {
  await goToWithRetry('sol_belt');
}
