export default async function main() {
  const present = await orient();

  let book: MarketBook;
  try {
    book = decode(MarketBook, await readMarket());
  } catch (e) {
    if (isError(e, 'BadData')) {
      note('bad book');
      return;
    }
    throw e;
  }

  // wanted: quantities of items to sell (those with best_buy >= 10)
  const wanted = new Map<string, number>();
  for (const row of present.cargo) {
    const q = book.rows.find((r) => r.item_id === row.item_id);
    if (q && q.best_buy >= 10) {
      wanted.set(row.item_id, (wanted.get(row.item_id) ?? 0) + row.quantity);
    }
  }

  if (wanted.size === 0) return;

  const rows = [...wanted.entries()].map(([item_id, quantity]) => ({item_id, quantity}));

  // Sell. A full sell can throw NoBuyer only if "nothing sold" per the spec,
  // but under a flaky market some fills can fail part-way. Retry the remainder.
  const done = new Map<string, number>();
  let rowsOut = rows;
  let attempts = 0;
  while (rowsOut.length > 0 && attempts < 10) {
    let sold;
    try {
      sold = await sell(rowsOut);
    } catch (e) {
      // Held short: the "short" names are the items no buyer took. Drop them, retry the rest.
      if (isError(e, 'NoBuyer')) {
        rowsOut = rowsOut.filter((r) => !(e.items as readonly string[]).includes(r.item_id));
        continue;
      }
      if (isError(e, 'NotDocked')) {
        const bases = e.bases as readonly string[];
        if (bases.length === 0) throw e;
        await goTo(bases[0]);
        continue;
      }
      // Anything else (InBattle, ServerBusy, …) — nothing sensible to do.
      throw e;
    }

    if (sold.total > 0) note(`sold for ${sold.total}`);

    for (const f of sold.fills) done.set(f.item_id, (done.get(f.item_id) ?? 0) + f.quantity);
    rowsOut = rowsOut
      .map((r) => {
        const taken = done.get(r.item_id) ?? 0;
        const left = r.quantity - taken;
        return left > 0 ? {...r, quantity: left} : null;
      })
      .filter((r): r is NonNullable<typeof r> => r !== null);
    attempts++;
  }

  // If everything that was wanted got sold, all cargo is gone; nothing to verify.
  if (rowsOut.length === 0) return;

  // Something is left: double-check current cargo and finish gracefully.
  const remaining = await orient();
  const leftItems = remaining.cargo.map((r) => r.item_id).sort();
  note(`left: ${leftItems.join(', ') || 'none'}`);
}
