import {orient, missions, acceptMission, completeMissions, note, isError} from 'play';

export default async function main(): Promise<number> {
  const me = await orient();

  if (me.in_battle) {
    await disengage();
    await orient();
  }

  if (!me.docked_at) {
    note(`not docked at ${me.poi}; cannot list missions`);
    return 0;
  }

  let list;
  try {
    list = await missions();
  } catch (e) {
    if (isError(e, 'NotDocked')) {
      note(`not docked at ${me.poi}; cannot list missions`);
      return 0;
    }
    throw e; // no better plan
  }

  let accepted = 0;
  for (const m of list) {
    if (m.reward < 100) continue;
    try {
      await acceptMission(m.id);
      accepted++;
      note(`accepted "${m.title}" (reward ${m.reward})`);
    } catch (e) {
      if (isError(e, 'NoSlots')) {
        note('no mission slots left; stopping accepts');
        break;
      }
      throw e; // no better plan
    }
  }

  try {
    const done = await completeMissions();
    note(`completed ${done.completed.length} mission(s); +${done.credits} credits`);
  } catch (e) {
    if (isError(e, 'NothingCompletable')) {
      note('nothing completable yet; carrying on');
    } else {
      throw e; // no better plan
    }
  }

  return accepted;
}
