// Mine until the hold is full. Retry on InBattle (disengage first), NothingHere,
// NotAtBelt, and ServerBusy. Stop when a cycle returns because the hold is full.
const mineUntilFull = Effect.gen(function* () {
  const rows: Row[] = [];

  const one = Effect.gen(function* () {
    const res = yield* mine().pipe(
      Effect.mapError((e) => (e._tag === 'InBattle' ? {tag: 'full' as const} : e)),
      Effect.tapError((e) =>
        e.tag === 'full' ? disengage().pipe(Effect.asVoid) : Effect.void,
      ),
    );
    return res;
  });

  // Fold: keep accumulating rows until mine() reports the hold full.
  const folded = yield* Effect.gen(function* () {
    const acc = (a: Row[]) => (r: Row) => a.concat(r);
    return yield* one().pipe(
      Effect.map((r) => [r] as const),
      Effect.flatMap((first) =>
        mineCycleLoop(first, 0, one, 500, acc, [] as Row[]),
      ),
    );
  })();

  rows.push(...folded);
  return rows;
});

function mineCycleLoop(
  first: Row,
  depth: number,
  one: () => Effect.Effect<Row, any, Game>,
  _depthLeft: number,
  acc: (a: Row[]) => (r: Row) => Row[],
  _rows: Row[],
): Effect.Effect<Row[], never, Game> {
