    Effect.retry({
      // Only the transient ServerBusy error is retried; anything else is thrown
      // (to the runtime) instead of fed back into the schedule.
      while: (e): boolean => e._tag === 'ServerBusy',
      // Exponential backoff, 1 second base, ×2 factor, capped after 5 retries.
      schedule: Schedule.exponential(1_000, {factor: 2}).pipe(Schedule.recurs(5)),
    }),
  );

export default Effect.gen(function* () {
  yield* go('sol_belt');
  yield* note('docked at sol_belt');
});
