  goTo,
  mine,
  sell,
  service,
  completeMissions,
  note,
  orient,
  prices,
  MarketBook,
  InBattle,
  HoldFull,
  NoBuyer,
  NotDocked,
  NothingCompletable,
  UnknownPlace,
  NoFuel,
  ServerBusy,
  type Row,
  type GameError,
} from 'play';

/**
 * Reflight a leg after an InBattle engagement, retrying goTo until we make it.
 * Each attempt disengages first so the leg can actually start.
 */
const reflight = (poi: string, engine: string) =>
  Effect.gen(function* () {
    yield* disengageLoop(engine);
    return yield* goTo(poi);
  }).pipe(
    Effect.retry({
      Schedule: Schedule.recurring(100, 10),
      errors: (e: GameError) => e._tag === 'InBattle' || e._tag === 'UnknownPlace' || e._tag === 'NoFuel' || e._tag === 'ServerBusy',
    }),
  );

/**
 * Repeatedly disengage until no battle remains, then we can proceed.
 */
const disengageLoop = (engine: string) =>
  Effect.gen(function* () {
    let inBattle = true;
    while (inBattle) {
      inBattle = yield* disengage();
    }
  }).pipe(Effect.ignore);

import {disengage} from 'play';

/**
 * Turn over the book at the dock to find the best single-credit item to grab.
 */
const bestFreeItem = () =>
  Effect.gen(function* () {
    const raw = yield* readMarket().pipe(
      Effect.map((raw) => Schema.decodeUnknown(MarketBook)(raw)),
      Effect.orElseSucceed((e) => null as null | {base: string; rows: readonly {item_id: string; best_buy: number; best_sell: number}[]}),
    );
    if (raw === null) return null as null | {item_id: string; quantity: number};
    // Any row where we can afford to buy something but have none held is a candidate.
    const rows = raw.rows;
    let best: {item_id: string; quantity: number} | null = null;
    let bestVal = 0;
    for (const r of rows) {
      if (r.best_buy <= 0) continue; // free or dirt cheap
      const val = -r.best_buy; // lower is better
      if (best === null || val < bestVal) {
        best = {item_id: r.item_id, quantity: 1};
        bestVal = val;
      }
    }
    return best;
  });

import {readMarket} from 'play';

/**
 * Mine a belt until the hold is full. Recovers from transient battle engagement.
 */
const mineUntilFull = (belt: string, engine: string) =>
  Effect.gen(function* () {
    // Step 1: actually be at the belt (starting from docked base), with retries.
    yield* reflight(belt, engine);

    // Step 2: mine until HoldFull. Each InBattle: disengage, then reflight to the belt.
    let rows: Row[] = [];
    while (true) {
      const res = yield* mine().pipe(
        Effect.either(),
      );
      if (res._tag === 'Right') {
        rows = rows.concat(res.right);
        continue; // not full yet (or maybe full but mine succeeded w/ fewer) — keep going
      }
      const err = res.left as GameError;
      if (err._tag === 'HoldFull') {
        return rows; // hold full, done
      }
      if (err._tag === 'InBattle') {
        // pirates hit — bail and get back to the belt
        yield* disengageLoop(engine);
        yield* reflight(belt, engine);
        continue;
      }
      // any other failure while mining: bail out of the mining loop
      return rows;
    }
  });

export default Effect.gen(function* () {
  // Reference labels for narration.
  const mine = 'sol_belt';
  const belt = 'kepler_belt';
  const base = 'kepler_base';

  // ── 1: Fly to kepler_belt ────────────────────────────────────────────────
  let rows: Row[] = [];
  try {
    rows = yield* mineUntilFull(belt, 'iron_ore').pipe(
      Effect.mapError(() => new InBattle({enemy: 'unknown'})),
    );
  } catch {
    // step failed — keep going
  }

  // ── 2: Go to kepler_base ─────────────────────────────────────────────────
  try {
    yield* goTo(base).pipe(
      Effect.retry({Schedule: Schedule.recurring(100, 5)}),
    );
  } catch {
    // step failed
  }

  // ── 3: Sell (everything we're holding) + fudge for NoBuyer ──────────────
  try {
    const info = yield* orient();
    const cargo: Row[] = info.cargo.map((r) => ({item_id: r.item_id, quantity: r.quantity}));
    if (cargo.length > 0) {
      yield* sell(cargo).pipe(
        Effect.catchTag('NoBuyer', () => bestFreeItem().pipe(
          Effect.flatMap((item) =>
            item === null
              ? Effect.fail(new NoBuyer({items: [] as readonly string[]}))
              : sell([item]),
          ),
        )),
      );
    }
  } catch {
    // step failed
  }

  // ── 4: Service the ship ──────────────────────────────────────────────────
  try {
    yield* service();
  } catch {
    // step failed
  }

  // ── 5: Complete missions (ignore NothingCompletable) ─────────────────────
  try {
    yield* completeMissions().pipe(
      Effect.catchTag('NothingCompletable', () => Effect.void),
    );
  } catch {
    // step failed
  }

  // ── 6: Always — note current credits ─────────────────────────────────────
  const p = yield* orient();
  yield* note(`credits: ${p.credits}`);
  return p.credits;
});

