import {goTo, sleep} from 'play';
import type {Arrived} from 'play';

// Retries goTo only on ServerBusy, with exponential backoff from 1s, at most 5 retries.
// Any other rejection is re-thrown (fails the program).
async function goToWithRetry(id: string): Promise<Arrived> {
  let delayMs = 1000;
  for (let attempt = 0; attempt <= 5; attempt++) {
    try {
      return await goTo(id);
    } catch (e: any) {
      const isBusy = e != null && typeof e === 'object' && e._tag === 'ServerBusy';
      if (!isBusy) throw e;
      if (attempt < 5) {
        await sleep(delayMs);
        delayMs *= 2;
      }
    }
  }
  throw new Error('unreachable: retries exhausted');
}

export default async function main() {
  await goToWithRetry('sol_belt');
}
