import {goTo, mine, sell, orient, service, note} from 'play';

export default Effect.gen(function* () {
  // Mine at the belt until the hold is full.
  // `mine()` yields a Row while there is room, and fails with `HoldFull`
  // when a cycle would overflow. `repeatUntilError` keeps going while it succeeds,
  // stopping at the first error (which is exactly what we want).
  yield* mine().pipe(Effect.repeatUntilError(), Effect.void);

  // Fly back to the base and dock.
  yield* goTo('sol_base');

  // Look at what we actually hold so we can sell every item, no leftovers.
  const present = yield* orient();
  const items = present.cargo.map((row) => ({item_id: row.item_id, quantity: row.quantity}));

  if (items.length === 0) {
    yield* note('hold was already empty; nothing to sell');
  } else {
    yield* sell(items).pipe(
      Effect.match({
        onFailure: (err) => note(`sell failed: ${err._tag}`),
        onSuccess: (sold) => note(`sold ${sold.fills.length} lot(s) for ${sold.total}`),
      }),
    );
  }

  // Top the ship back off before heading out again.
  return yield* service();
