    (best, q) => (q.best_buy > best.best_buy ? q : best),
    {item_id: '', best_buy: -Infinity},
  );

  yield* note(
    `credits ${me.credits}; highest best_buy is ${top.item_id} at ${top.best_buy}; ${activeCount} mission(s) available`,
  );
