import {
  orient,
  readMarket,
  sell,
  service,
  note,
  decode,
  MarketBook,
  isError,
} from 'play';

export default async function main() {
  // Start docked at sol_base, but confirm where we actually are.
  const here = await orient();
  note(`started at ${here.poi}, docked at ${here.docked_at ?? 'nowhere'}, holding ${here.cargo.length} rows`);

  let soldTotal = 0;
  let kept: {item_id: string; quantity: number}[] = [];
  let sold: {item_id: string; quantity: number}[] = [];

  let book: unknown;
  try {
    book = await readMarket();
  } catch (e) {
    // A rejected read (NoBuyer/NotDocked/etc.) — nothing to sell from the book.
    note(`readMarket rejected (${(e as { _tag?: string })?._tag ?? 'unknown'}); nothing to sell`);
    kept = [...here.cargo];
    book = null; // marks "no book" below
  }

  if (book !== null) {
    let decoded;
    try {
      decoded = decode(MarketBook, book);
    } catch (e) {
      if (isError(e, 'BadData')) {
        note('bad book');
        kept = [...here.cargo];
        book = null; // no book -> keep everything, finish without failing
      } else {
        throw e; // unexpected error, propagate
      }
    }

    if (book !== null && decoded !== undefined) {
      // Map item_id -> best_buy for quick lookup.
      const bestBuy = new Map<string, number>();
      for (const row of (decoded as { rows: { item_id: string; best_buy: number }[] }).rows) {
        bestBuy.set(row.item_id, row.best_buy);
      }

      for (const row of here.cargo) {
        const bb = bestBuy.get(row.item_id);
        if (bb !== undefined && bb >= 10) {
          sold.push({item_id: row.item_id, quantity: row.quantity});
        } else {
          kept.push({item_id: row.item_id, quantity: row.quantity});
        }
      }

      if (sold.length > 0) {
        try {
          const res = await sell(sold);
          soldTotal = res.total;
          note(`sold ${res.fills.length} line(s) for ${res.total}`);
          if (res.short.length > 0) {
            note(`short on: ${res.short.join(', ')}`);
          }
        } catch (e) {
          if (isError(e, 'InBattle')) {
            note('in battle during sell; could not sell');
            // Move everything we planned to sell into kept since the sell failed
            for (const s of sold) kept.push(s);
            sold = [];
          } else if (isError(e, 'NotDocked')) {
            note('not docked during sell; could not sell');
            for (const s of sold) kept.push(s);
            sold = [];
          } else if (isError(e, 'NoBuyer')) {
            note(`NoBuyer for: ${e.items.join(', ')}; keeping those`);
            // We don't know exactly which lines failed to sell; re-keep all planned-sell
            // items since the book threshold check is our only signal.
            for (const s of sold) kept.push(s);
            sold = [];
          } else {
            throw e; // unexpected
          }
        }
      }
    }
  }

  note(`final: selling ${sold.length} row(s), keeping ${kept.length} row(s)`);

  // Full tank, full hull to finish cleanly.
  try {
    await service();
  } catch (e) {
    if (isError(e, 'NotDocked')) {
      note('not docked; skipped service');
    } else {
      throw e;
    }
  }

  return soldTotal;
}
