import {Effect, Schedule} from 'effect';
import {
  orient,
  mine,
  goTo,
  sell,
  service,
  completeMissions,
  disengage,
  note,
} from 'play';

// One mining cycle: mine; if pirates show up, disengage and mine again.
const mineCycle = Effect.gen(function* () {
  try {
    return yield* mine();
  } catch (e) {
    if (typeof e === 'object' && e !== null && '_tag' in e && e._tag === 'InBattle') {
      yield* disengage();
      return yield* mineCycle();
    }
    throw e;
  }
});

// Mine until the hold is full. Other mining failures bubble up to the caller.
const mineUntilFull = Effect.gen(function* () {
  while (true) {
    const take = yield* mineCycle();
    const present = yield* orient();
    if (present.cargo_used >= present.cargo_capacity) {
      return take;
    }
  }
});

// Succeed with the Sold result, or re-throw an Unexpected error for the caller.
const sellCopper = Effect.gen(function* () {
  try {
    return yield* sell([{item_id: 'copper_ore'}]);
  } catch (e) {
    if (typeof e === 'object' && e !== null && '_tag' in e && e._tag === 'Unexpected') {
      throw e;
    }
    return e; // Sold
  }
});

// One attempt at the whole plan. Aborts in 10s, returns the error tag it died on.
const attempt = Effect.gen(function* () {
  yield* goTo('kepler_belt').pipe(
    Effect.either,
    Effect.map(e => {
      const tag = e && typeof e === 'object' && '_tag' in e ? (e as {_tag: string})._tag : 'Unknown';
      return new Error(tag);
    }),
  );
  yield* mineUntilFull();
  yield* goTo('kepler_base');
  yield* sellCopper();
  yield* service();
  const c = yield* completeMissions().pipe(
    Effect.catchTag('NothingCompletable', () =>
      Effect.gen(function* () {
        return null;
      }),
    ),
  );
  yield* note(`completed ${c === null ? 0 : c.completed.length} mission(s)`);
});

export default Effect.gen(function* () {
  try {
    yield* attempt.pipe(Effect.timeout({duration: 10_000, onTimeout: () => new Error('Timeout')}));
  } catch (e) {
    if (typeof e === 'object' && e !== null && '_tag' in e && e._tag === 'Unexpected') {
      throw e;
    }
    yield* note(`plan aborted: ${e instanceof Error ? e.message : String(e)}`);
  }
  const present = yield* orient().pipe(
    Effect.catchTags({
      ServerBusy: () =>
        Effect.retryable(
          Effect.gen(function* () {
            const p = yield* orient();
            if (p.in_battle) yield* disengage();
            return p;
          }),
          {
            times: 10,
            schedule: Schedule.recurs(10).pipe(Schedule.intersect(Schedule.exponential({factor: 2, jitter: false}))),
          },
        ),
    }),
  );
  yield* note(`credits: ${present.credits}`);
});
